const fs = require('fs');

const translations = {
  "AELEC": "AELEC",
  "Asociación Española de Empresas de Electricidad. Agrupa a las principales empresas del sector eléctrico español. Cofinanció el informe IIT-ICAI.": "Associazione Spagnola delle Imprese di Elettricità. Raggruppa le principali imprese del settore elettrico spagnolo. Ha cofinanziato il rapporto IIT-ICAI.",
  "aFRR": "aFRR",
  "Automatic Frequency Restoration Reserve. La aFRR (automatic Frequency Restoration Reserve), históricamente conocida como regulación secundaria, es un servicio de ajuste del sistema que se activa automáticamente tras una desviación de frecuencia. Está controlado directamente por el AGC (Automatic Generation Control) del Operador del Sistema y su objetivo es devolver progresivamente la frecuencia a su valor nominal (50 Hz) y restituir los flujos en las interconexiones a sus programas pactados.": "Automatic Frequency Restoration Reserve. L'aFRR (automatic Frequency Restoration Reserve), storicamente conosciuta come regolazione secondaria, è un servizio di aggiustamento del sistema che si attiva automaticamente in seguito a una deviazione di frequenza. È controllato direttamente dall'AGC (Automatic Generation Control) dell'Operatore di Sistema e il suo obiettivo è riportare progressivamente la frequenza al suo valore nominale (50 Hz) e ripristinare i flussi nelle interconnessioni ai programmi concordati.",
  "Área de Control": "Area di Controllo",
  "Zona geográfica bajo responsabilidad de un Operador del Sistema (OS).": "Zona geografica sotto la responsabilità di un Operatore di Sistema (OS).",
  "Arranque autónomo (Black Start)": "Avvio autonomo (Black Start)",
  "La capacidad de Black Start (arranque autónomo o arranque en negro) es el servicio de ajuste por el cual ciertas instalaciones de generación pueden arrancar y comenzar a inyectar energía a la red sin necesidad de recibir tensión eléctrica externa.": "La capacità di Black Start (avvio autonomo o avvio in nero) è il servizio di aggiustamento mediante il quale alcune strutture di generazione possono avviarsi e iniziare a iniettare energia nella rete senza necessità di ricevere tensione elettrica esterna.",
  "BESS": "BESS",
  "Battery Energy Storage System.": "Battery Energy Storage System.",
  "BESS con inversores Grid-Forming (BESS-GFM)": "BESS con inverter Grid-Forming (BESS-GFM)",
  "Los Sistemas de Almacenamiento en Baterías con Inversores Formadores de Red (BESS-GFM) combinan alta densidad electroquímica con electrónica de potencia capaz de operar como una fuente de tensión ideal y autónoma.": "I Sistemi di Accumulo a Batteria con Inverter Formatori di Rete (BESS-GFM) combinano un'alta densità elettrochimica con un'elettronica di potenza in grado di operare come una fonte di tensione ideale e autonoma.",
  "Bucle de retroalimentación (Feedback loop)": "Ciclo di retroazione (Feedback loop)",
  "Un feedback loop positivo, o bucle de retroalimentación positiva, describe un mecanismo en el que una perturbación inicial provoca una respuesta del sistema que, en lugar de oponerse al desvío, lo amplifica. En el contexto del incidente, cada disparo de planta IBR redujo la absorción de reactiva, lo que elevó la tensión, lo que a su vez provocó nuevos disparos: la respuesta del sistema reforzaba la perturbación en lugar de amortiguarla.": "Un feedback loop positivo, o ciclo di retroazione positiva, descrive un meccanismo in cui una perturbazione iniziale provoca una risposta del sistema che, invece di contrastare la deviazione, la amplifica. Nel contesto dell'incidente, ogni scatto di un impianto IBR ha ridotto l'assorbimento di reattiva, sollevando la tensione, il che a sua volta ha provocato nuovi scatti: la risposta del sistema rafforzava la perturbazione invece di smorzarla.",
  "Cambiadores de Tomas en Carga (OLTC)": "Commutatori di Prese Sotto Carico (OLTC)",
  "Un Cambiador de Tomas en Carga (OLTC, On-Load Tap Changer) es un mecanismo electromecánico instalado en los grandes transformadores de potencia que ajusta la relación de transformación —y, por tanto, la tensión de salida del secundario— sin interrumpir el flujo de energía. Regula la tensión ante variaciones lentas de carga, típicamente en un rango de ±10% con escalones discretos. Su tiempo característico de respuesta, condicionado por la inercia mecánica del motor y los engranajes, es del orden de varios segundos por escalón.": "Un Commutatore di Prese Sotto Carico (OLTC, On-Load Tap Changer) è un meccanismo elettromeccanico installato nei grandi trasformatori di potenza che regola il rapporto di trasformazione —e, di conseguenza, la tensione di uscita del secondario— senza interrompere il flusso di energia. Regola la tensione di fronte a lente variazioni di carico, tipicamente in un intervallo del ±10% con gradini discreti. Il suo tempo di risposta caratteristico, condizionato dall'inerzia meccanica del motore e degli ingranaggi, è dell'ordine di diversi secondi per gradino.",
  "CCGT": "CCGT",
  "Combined Cycle Gas Turbine.": "Combined Cycle Gas Turbine.",
  "CECRE": "CECRE",
  "Centro de Control de Energías Renovables. El Centro de Control de Energías Renovables (CECRE) es la entidad operativa de REE responsable de la monitorización y despacho en tiempo real de los parques renovables y los sistemas de almacenamiento, así como de la ejecución de los algoritmos de control de tensión a través del sistema VOLTAIRE.": "Centro di Controllo delle Energie Rinnovabili. Il Centro di Controllo delle Energie Rinnovabili (CECRE) è l'entità operativa di REE responsabile del monitoraggio e del dispacciamento in tempo reale dei parchi rinnovabili e dei sistemi di accumulo, nonché dell'esecuzione degli algoritmi di controllo della tensione attraverso il sistema VOLTAIRE.",
  "Centros de Coordinación Regional (RCC)": "Centri di Coordinamento Regionale (RCC)",
  "Los Centros de Coordinación Regional (RCC, Regional Coordination Centres) son entidades supranacionales establecidas por la normativa europea para facilitar la cooperación operativa entre los distintos Gestores de Redes de Transporte (TSO).": "I Centri di Coordinamento Regionale (RCC, Regional Coordination Centres) sono entità sovranazionali stabilite dalla normativa europea per facilitare la cooperazione operativa tra i diversi Gestori di Reti di Trasmissione (TSO).",
  "Colapso Q-V": "Collasso Q-V",
  "Inestabilidad de tensión en el plano potencia reactiva–voltaje. Mecanismo dominante del 28A (no colapso de frecuencia).": "Instabilità di tensione nel piano potenza reattiva-tensione. Meccanismo dominante del 28A (non collasso di frequenza).",
  "Compensadores Síncronos (SynCons)": "Compensatori Sincroni (SynCons)",
  "Los Compensadores Síncronos son máquinas rotativas síncronas operadas en vacío —sin turbina primaria— que aportan inercia rotacional genuina y capacidad de inyección de corrientes de falta de 300–400% de su valor nominal.": "I Compensatori Sincroni sono macchine rotanti sincrone azionate a vuoto —senza turbina primaria— che forniscono un'inerzia rotazionale genuina e una capacità di iniezione di correnti di guasto del 300–400% del loro valore nominale.",
  "Compensador Síncrono Estático (STATCOM)": "Compensatore Sincrono Statico (STATCOM)",
  "Un STATCOM (Static Synchronous Compensator) es un dispositivo de compensación activa de potencia reactiva basado en electrónica de potencia (inversores VSC). A diferencia de las reactancias o los bancos de condensadores mecánicos de conmutación discreta, un STATCOM inyecta o absorbe potencia reactiva de forma continua, dinámica y casi instantánea.": "Uno STATCOM (Static Synchronous Compensator) è un dispositivo di compensazione attiva di potenza reattiva basato sull'elettronica di potenza (inverter VSC). A differenza delle reattanze o dei banchi di condensatori meccanici a commutazione discreta, uno STATCOM inietta o assorbe potenza reattiva in modo continuo, dinamico e quasi istantaneo.",
  "Control Grid-forming frente a Grid-following": "Controllo Grid-forming rispetto a Grid-following",
  "Este concepto define el paradigma de control de los inversores. Un inversor grid-following (seguidor de red) se sincroniza pasivamente con la tensión y frecuencia preexistentes, dependiendo de la red externa para operar. Por el contrario, un inversor grid-forming (formador de red) actúa como una fuente de tensión ideal tras una impedancia: establece activamente su propia onda de tensión y frecuencia, permitiendo sostener la red de forma autónoma.": "Questo concetto definisce il paradigma di controllo degli inverter. Un inverter grid-following (inseguitore di rete) si sincronizza passivamente con la tensione e frequenza preesistenti, dipendendo dalla rete esterna per operare. Al contrario, un inverter grid-forming (formatore di rete) agisce come una fonte di tensione ideale dietro a un'impedenza: stabilisce attivamente la propria onda di tensione e frequenza, permettendo di sostenere la rete in modo autonomo.",
  "Coste Nivelado de la Energía (LCOE)": "Costo Livellato dell'Energia (LCOE)",
  "El Coste Nivelado de la Energía (LCOE) es la métrica económica estándar que compara el coste unitario de producción entre distintas tecnologías a lo largo de su vida útil. Su principal limitación sistémica es que ignora el valor de los servicios ancilares aportados a la red.": "Il Costo Livellato dell'Energia (LCOE) è la metrica economica standard che confronta il costo unitario di produzione tra diverse tecnologie lungo la loro vita utile. La sua principale limitazione sistemica è che ignora il valore dei servizi ancillari forniti alla rete.",
  "Crisis communication failure": "Fallimento nella comunicazione di crisi",
  "En gestión de emergencias, un crisis communication failure describe el fallo institucional al no ocupar de forma oportuna el espacio informativo con mensajes verificables tras un incidente grave. Según el Chaos Communication Model, si la institución responsable no emite un relato claro durante la ventana crítica inicial (1-6 horas), el vacío discursivo es ocupado por narrativas alternativas o no verificadas.": "Nella gestione delle emergenze, un crisis communication failure descrive il fallimento istituzionale nel non occupare in modo tempestivo lo spazio informativo con messaggi verificabili dopo un incidente grave. Secondo il Chaos Communication Model, se l'istituzione responsabile non emette un racconto chiaro durante la finestra critica iniziale (1-6 ore), il vuoto discorsivo viene occupato da narrative alternative o non verificate.",
  "Criterio N-1": "Criterio N-1",
  "El Criterio N-1 es la norma de seguridad fundamental en la operación y planificación de sistemas eléctricos de potencia. Establece que el sistema debe ser capaz de mantener los parámetros de tensión y frecuencia dentro de los límites operativos normativos tras la pérdida contingente de cualquier elemento único, sin provocar cortes de suministro en cascada ni daños en los equipos.": "Il Criterio N-1 è la norma di sicurezza fondamentale nell'operazione e pianificazione dei sistemi elettrici di potenza. Stabilisce che il sistema deve essere in grado di mantenere i parametri di tensione e frequenza entro i limiti operativi normativi dopo la perdita contingente di qualsiasi elemento singolo, senza provocare interruzioni di fornitura a cascata o danni alle apparecchiature.",
  "CSN": "CSN",
  "Consejo de Seguridad Nacional de España. Publicó el informe oficial del Gobierno junto con REE.": "Consiglio di Sicurezza Nazionale della Spagna. Ha pubblicato il rapporto ufficiale del Governo insieme a REE.",
  "Curva de capacidad reactiva (Capability Curve)": "Curva di capacità reattiva (Capability Curve)",
  "Diagrama P-Q que delimita el espacio operativo de un generador en el plano potencia activa-reactiva.": "Diagramma P-Q che delimita lo spazio operativo di un generatore nel piano potenza attiva-reattiva.",
  "Curva de Pato (Duck Curve)": "Curva ad Anatra (Duck Curve)",
  "La curva de pato describe el perfil diario de demanda neta de regulación en sistemas con alta penetración solar: una depresión profunda durante las horas centrales del día seguida de una rampa vespertina pronunciada.": "La curva ad anatra descrive il profilo giornaliero della domanda netta di regolazione nei sistemi con un'elevata penetrazione solare: una depressione profonda durante le ore centrali della giornata seguita da una ripida rampa serale.",
  "Curvas de estabilidad de tensión Q-V": "Curve di stabilità di tensione Q-V",
  "Las curvas Q-V representan, para un nudo dado de la red, la relación entre la potencia reactiva inyectada o absorbida y la tensión resultante. La distancia entre el punto de operación y el punto de mínimo de la curva (nose point) define el margen de estabilidad de tensión: cuanto menor sea ese margen, mayor será el riesgo de un colapso de tensión ante perturbaciones adicionales.": "Le curve Q-V rappresentano, per un dato nodo della rete, la relazione tra la potenza reattiva iniettata o assorbita e la tensione risultante. La distanza tra il punto di operazione e il punto di minimo della curva (nose point) definisce il margine di stabilità di tensione: minore è questo margine, maggiore sarà il rischio di un collasso di tensione a fronte di ulteriori perturbazioni.",
  "Damping ratio": "Rapporto di smorzamento (Damping ratio)",
  "El ratio de amortiguamiento (o amortiguamiento relativo) es un indicador adimensional que cuantifica la rapidez con la que una oscilación se atenúa tras una perturbación. Valores próximos al 5% se consideran un margen de seguridad operativo razonable en el sistema síncrono europeo; valores cercanos al 0% indican oscilaciones sostenidas, y valores negativos implican un crecimiento de la amplitud y, por tanto, un riesgo de inestabilidad.": "Il rapporto di smorzamento (o smorzamento relativo) è un indicatore adimensionale che quantifica la rapidità con cui un'oscillazione si attenua dopo una perturbazione. Valori prossimi al 5% sono considerati un margine di sicurezza operativo ragionevole nel sistema sincrono europeo; valori vicini allo 0% indicano oscillazioni sostenute, e valori negativi implicano una crescita dell'ampiezza e, quindi, un rischio di instabilità.",
  "EAS (ENTSO-E Awareness System)": "EAS (ENTSO-E Awareness System)",
  "ENTSO-E Awareness System. Sistema de Conciencia Situacional de ENTSO-E que monitorea la estabilidad de la red europea en tiempo real.": "ENTSO-E Awareness System. Sistema di Consapevolezza Situazionale di ENTSO-E che monitora la stabilità della rete europea in tempo reale.",
  "EAS": "EAS",
  "ENTSO-E Awareness System.": "ENTSO-E Awareness System.",
  "Efecto Ferranti": "Effetto Ferranti",
  "El Efecto Ferranti describe el fenómeno por el cual, en una línea de transporte de alta tensión operada con poca o ninguna carga, la tensión en el extremo receptor supera a la del extremo emisor. La causa es la admitancia capacitiva distribuida de la línea: con flujo de potencia activa reducido, la carga capacitiva no se compensa con el consumo inductivo de las cargas, y el resultado es una sobretensión proporcional a la longitud de la línea. Es un fenómeno especialmente relevante al energizar líneas de 400 kV en vacío.": "L'Effetto Ferranti descrive il fenomeno per cui, in una linea di trasmissione ad alta tensione operata con poco o nessun carico, la tensione all'estremità ricevente supera quella dell'estremità trasmittente. La causa è l'ammettenza capacitiva distribuita della linea: con un flusso di potenza attiva ridotto, il carico capacitivo non viene compensato dal consumo induttivo dei carichi, e il risultato è una sovratensione proporzionale alla lunghezza della linea. È un fenomeno particolarmente rilevante quando si energizzano linee a 400 kV a vuoto.",
  "Emergent norm theory": "Teoria delle norme emergenti",
  "La teoría de las normas emergentes (Turner y Killian) sostiene que, frente a las visiones del pánico masivo, los grupos en situaciones de disrupción desarrollan espontáneamente nuevas reglas de comportamiento social adaptativo.": "La teoria delle norme emergenti (Turner e Killian) sostiene che, di fronte alle visioni di panico di massa, i gruppi in situazioni di disturbo sviluppano spontaneamente nuove regole di comportamento sociale adattativo.",
  "Encuadre mediático (Framing) y Agenda-shifting": "Inquadramento mediatico (Framing) e Spostamento dell'agenda (Agenda-shifting)",
  "El framing es el proceso por el cual los medios seleccionan y enfatizan ciertos elementos de un hecho para proponer una interpretación causal concreta. Relacionado con esto, el agenda-shifting ocurre cuando un evento disruptivo es instrumentalizado mediáticamente para desplazar la atención y reabrir debates políticos o estructurales preexistentes.": "Il framing è il processo attraverso il quale i media selezionano ed enfatizzano determinati elementi di un fatto per proporre un'interpretazione causale concreta. In relazione a ciò, l'agenda-shifting si verifica quando un evento dirompente viene strumentalizzato dai media per spostare l'attenzione e riaprire dibattiti politici o strutturali preesistenti.",
  "ENTSO-E": "ENTSO-E",
  "La Red Europea de Gestores de Redes de Transporte de Electricidad (ENTSO-E, por sus siglas en inglés: European Network of Transmission System Operators for Electricity) es la asociación que agrupa a 40 operadores técnicos de red (TSO) pertenecientes a 36 países europeos. Su mandato principal, derivado de los sucesivos paquetes legislativos de la Unión Europea, es garantizar la seguridad y fiabilidad de la operación del sistema interconectado europeo, facilitar la integración de energías renovables y establecer los códigos de red comunes (Network Codes) de obligado cumplimiento para todos los Estados miembros.": "La Rete Europea dei Gestori dei Sistemi di Trasmissione dell'Elettricità (ENTSO-E, acronimo inglese: European Network of Transmission System Operators for Electricity) è l'associazione che raggruppa 40 operatori tecnici di rete (TSO) appartenenti a 36 paesi europei. Il suo mandato principale, derivante dai successivi pacchetti legislativi dell'Unione Europea, è garantire la sicurezza e l'affidabilità del funzionamento del sistema interconnesso europeo, facilitare l'integrazione delle energie rinnovabili e stabilire i codici di rete comuni (Network Codes) vincolanti per tutti gli Stati membri.",
  "ERS": "ERS",
  "Essential Reliability Services.": "Servizi Essenziali di Affidabilità.",
  "Estabilidad de tensión": "Stabilità di tensione",
  "Capacidad del sistema para mantener tensiones dentro de límites operacionales tras perturbaciones. Requiere balance entre demanda y aportación de potencia reactiva.": "Capacità del sistema di mantenere le tensioni entro limiti operativi dopo perturbazioni. Richiede equilibrio tra domanda e fornitura di potenza reattiva.",
  "Estabilizadores del Sistema de Potencia (PSS)": "Stabilizzatori del Sistema di Potenza (PSS)",
  "Los PSS (Power System Stabilizers) son lazos de control adicionales instalados en el sistema de excitación de los grandes generadores síncronos que añaden amortiguamiento eléctrico a las oscilaciones electromecánicas del sistema.": "I PSS (Power System Stabilizers) sono anelli di controllo aggiuntivi installati nel sistema di eccitazione dei grandi generatori sincroni che aggiungono smorzamento elettrico alle oscillazioni elettromeccaniche del sistema.",
  "Estrategia Brownfield": "Strategia Brownfield",
  "En ingeniería de infraestructuras energéticas, la estrategia Brownfield consiste en la reconversión de instalaciones industriales existentes —como las centrales térmicas o nucleares clausuradas— para dotarlas de nuevas funciones sistémicas, como convertirlas en compensadores síncronos.": "Nell'ingegneria delle infrastrutture energetiche, la strategia Brownfield consiste nella riconversione di impianti industriali esistenti —come centrali termiche o nucleari chiuse— per dotarli di nuove funzioni sistemiche, come trasformarli in compensatori sincroni.",
  "Fast Frequency Response (FFR)": "Risposta Rapida in Frequenza (FFR)",
  "La Respuesta Rápida de Frecuencia (FFR) es un servicio de estabilización subcíclica, diseñado para sistemas de electrónica de potencia, que inyecta un bloque masivo de potencia activa en la ventana temporal crítica (típicamente inferior a 0,25 s) previa a la actuación de los reguladores mecánicos tradicionales.": "La Risposta Rapida di Frequenza (FFR) è un servizio di stabilizzazione sub-ciclica, progettato per sistemi di elettronica di potenza, che inietta un blocco massiccio di potenza attiva nella finestra temporale critica (tipicamente inferiore a 0,25 s) prima dell'intervento dei regolatori meccanici tradizionali.",
  "FFR": "FFR",
  "Fast Frequency Response.": "Fast Frequency Response.",
  "Frecuencia nominal": "Frequenza nominale",
  "50 Hz en el sistema europeo continental. El P.O. 1.1 define los límites de operación: f ∈ [49,0; 51,0] Hz en operación normal.": "50 Hz nel sistema europeo continentale. Il P.O. 1.1 definisce i limiti di funzionamento: f ∈ [49,0; 51,0] Hz in funzionamento normale.",
  "GFL": "GFL",
  "Grid-Following Inverter.": "Inverter Grid-Following.",
  "GFM": "GFM",
  "Grid-Forming Inverter.": "Inverter Grid-Forming.",
  "Headroom: Reserva de Capacidad del Inversor": "Headroom: Riserva di Capacità dell'Inverter",
  "El headroom es la fracción de la capacidad aparente máxima que un inversor GFM debe mantener reservada sin utilizarla para la inyección de potencia activa en estado estacionario, con el fin de tener margen para responder a transitorios rápidos.": "L'headroom è la frazione della capacità apparente massima che un inverter GFM deve mantenere riservata senza utilizzarla per l'iniezione di potenza attiva in stato stazionario, al fine di avere margine per rispondere a transitori rapidi.",
  "HVDC": "HVDC",
  "High Voltage Direct Current.": "High Voltage Direct Current (Corrente Continua ad Alta Tensione).",
  "IBR": "IBR",
  "Inverter-Based Resources.": "Risorse Basate su Inverter.",
  "IGBT (Insulated Gate Bipolar Transistor)": "IGBT (Insulated Gate Bipolar Transistor)",
  "Semiconductor de potencia utilizado en inversores. Control de compuerta aislada permite conmutación rápida y eficiente.": "Semiconduttore di potenza utilizzato negli inverter. Il controllo del gate isolato consente una commutazione rapida ed efficiente.",
  "Impedancia de transferencia": "Impedenza di trasferimento",
  "En sistemas de potencia, la impedancia de transferencia entre dos nudos representa la oposición eléctrica al flujo de potencia entre ellos. Una alta impedancia de transferencia implica una red débilmente acoplada, en la que pequeñas variaciones de potencia inyectada pueden producir grandes variaciones de tensión y de ángulo de fase, deteriorando la firmeza del sistema.": "Nei sistemi di potenza, l'impedenza di trasferimento tra due nodi rappresenta l'opposizione elettrica al flusso di potenza tra di essi. Un'elevata impedenza di trasferimento implica una rete debolmente accoppiata, in cui piccole variazioni di potenza iniettata possono produrre ampie variazioni di tensione e di angolo di fase, compromettendo la stabilità del sistema.",
  "Infodemia": "Infodemia",
  "Término popularizado por la OMS para describir la sobrepoblación del espacio informativo con contenidos no verificados, erróneos o falsos que se propagan rápidamente en situaciones de crisis.": "Termine reso popolare dall'OMS per descrivere la sovrappopolazione dello spazio informativo con contenuti non verificati, errati o falsi che si diffondono rapidamente in situazioni di crisi.",
  "Inercia Sintética": "Inerzia Sintetica",
  "La inercia sintética (o inercia virtual) es un algoritmo de control implementado en inversores GFM que emula matemáticamente el comportamiento de la ecuación de oscilación de un rotor electromecánico. El algoritmo mide continuamente la derivada temporal de la frecuencia (df/dt) y ajusta la potencia inyectada de forma proporcional.": "L'inerzia sintetica (o inerzia virtuale) è un algoritmo di controllo implementato negli inverter GFM che emula matematicamente il comportamento dell'equazione di oscillazione di un rotore elettromeccanico. L'algoritmo misura continuamente la derivata temporale della frequenza (df/dt) e regola la potenza iniettata in modo proporzionale.",
  "LCOE": "LCOE",
  "Levelized Cost of Energy.": "Levelized Cost of Energy.",
  "Low Voltage Ride Through (LVRT)": "Low Voltage Ride Through (LVRT)",
  "El Low Voltage Ride Through (LVRT) es la capacidad de un inversor para mantener la inyección de energía durante un hueco de tensión en lugar de desconectarse por protección.": "Il Low Voltage Ride Through (LVRT) è la capacità di un inverter di mantenere l'iniezione di energia durante un buco di tensione invece di disconnettersi per protezione.",
  "Mallado": "Magliatura",
  "Maniobra operativa de reconfiguración topológica que conecta subestaciones previamente separadas mediante líneas de 400 kV. En el 28A activó el efecto Ferranti.": "Manovra operativa di riconfigurazione topologica che collega sottostazioni precedentemente separate mediante linee a 400 kV. Nel 28A ha innescato l'effetto Ferranti.",
  "Network Code on Requirements for Generators (NC RfG)": "Codice di Rete sui Requisiti per i Generatori (NC RfG)",
  "El Network Code on Requirements for Generators es el código de red europeo establecido por ENTSO-E que armoniza los requisitos técnicos obligatorios que deben cumplir las instalaciones de generación para conectarse a la red. Ahora en su versión 2.0, propuesta tras el colapso ibérico, introduce la obligatoriedad de capacidades grid-forming.": "Il Network Code on Requirements for Generators è il codice di rete europeo stabilito dall'ENTSO-E che armonizza i requisiti tecnici obbligatori che gli impianti di generazione devono soddisfare per connettersi alla rete. Ora nella sua versione 2.0, proposta dopo il collasso iberico, introduce l'obbligatorietà delle capacità grid-forming.",
  "OLTC": "OLTC",
  "On-Load Tap Changer.": "On-Load Tap Changer.",
  "OST": "OST",
  "Out-of-Step Tripping.": "Out-of-Step Tripping.",
  "Oscilaciones electromecánicas": "Oscillazioni elettromeccaniche",
  "Modos oscilatorios asociados a la interacción entre generadores síncronos. Típicamente 0,1–2 Hz. En el 28A se detectó oscilación de 0,6 Hz.": "Modi oscillatori associati all'interazione tra generatori sincroni. Tipicamente 0,1–2 Hz. Nel 28A è stata rilevata un'oscillazione di 0,6 Hz.",
  "Oscilaciones forzadas y naturales": "Oscillazioni forzate e naturali",
  "Una oscilación es forzada cuando es inducida por una perturbación externa periódica —típicamente un fallo o un comportamiento anómalo en el lazo de control de un equipo concreto—, frente a las oscilaciones naturales o modos propios del sistema, cuya frecuencia viene determinada por la propia inercia y por las constantes electromecánicas de las máquinas síncronas conectadas.": "Un'oscillazione è forzata quando è indotta da una perturbazione esterna periodica —tipicamente un guasto o un comportamento anomalo nell'anello di controllo di una specifica apparecchiatura—, rispetto alle oscillazioni naturali o modi propri del sistema, la cui frequenza è determinata dalla stessa inerzia e dalle costanti elettromeccaniche delle macchine sincrone connesse.",
  "Outrage communication (Comunicación de indignación)": "Outrage communication (Comunicazione dell'indignazione)",
  "Basado en el modelo de Sandman (Risk = Hazard + Outrage), este concepto indica que la percepción pública de un riesgo depende más de factores emocionales (indignación, percepción de negligencia) que de la evaluación técnica del peligro real.": "Basato sul modello di Sandman (Rischio = Pericolo + Indignazione), questo concetto indica che la percezione pubblica di un rischio dipende maggiormente da fattori emotivi (indignazione, percezione di negligenza) piuttosto che dalla valutazione tecnica del pericolo reale.",
  "PLL": "PLL",
  "Phase-Locked Loop.": "Phase-Locked Loop.",
  "PMU": "PMU",
  "Phasor Measurement Unit.": "Phasor Measurement Unit.",
  "PNIEC": "PNIEC",
  "Plan Nacional Integrado de Energía y Clima.": "Piano Nazionale Integrato per l'Energia e il Clima.",
  "Potencia de cortocircuito (Ssc)": "Potenza di cortocircuito (Ssc)",
  "La Potencia de Cortocircuito (Ssc) en un nudo es la magnitud instantánea de corriente que el sistema puede inyectar ante una falta de tensión. Define la rigidez eléctrica del nudo: un Ssc elevado permite que las protecciones de distancia operen correctamente, que las protecciones de sobrecorriente se coordinen selectivamente y que los inversores mantengan sincronismo de sus algoritmos de control.": "La Potenza di Cortocircuito (Ssc) in un nodo è la grandezza istantanea di corrente che il sistema può iniettare di fronte a una mancanza di tensione. Definisce la rigidità elettrica del nodo: un'elevata Ssc consente alle protezioni di distanza di operare correttamente, alle protezioni di sovracorrente di coordinarsi selettivamente e agli inverter di mantenere il sincronismo dei loro algoritmi di controllo.",
  "Power System Stabilizers y Power Oscillation Damping (PSS/POD)": "Stabilizzatori dei Sistemi di Potenza e Smorzamento delle Oscillazioni di Potenza (PSS/POD)",
  "Los Power System Stabilizers (PSS) y los sistemas de Power Oscillation Damping (POD) son módulos de control adicionales instalados en inversores (especialmente en modo GFM) que inyectan señales contrafase diseñadas para amortiguar oscilaciones electromecánicas de pequeña y gran perturbación.": "I Power System Stabilizers (PSS) e i sistemi di Power Oscillation Damping (POD) sono moduli di controllo aggiuntivi installati negli inverter (soprattutto in modalità GFM) che iniettano segnali in controfase progettati per smorzare oscillazioni elettromeccaniche di piccola e grande perturbazione.",
  "Procedimiento de Operación 1.6 (P.O. 1.6)": "Procedura Operativa 1.6 (P.O. 1.6)",
  "El Procedimiento de Operación 1.6 es el protocolo de emergencia del sistema eléctrico español que establece los planes de salvaguarda y reposición del suministro ante incidentes críticos. Dictamina las estrategias de fragmentación topológica de la red en islas eléctricas independientes, las rutas de energización preferentes y el protocolo de priorización de arranque de las instalaciones de generación para restaurar el sistema tras un cero de tensión parcial o total.": "La Procedura Operativa 1.6 è il protocollo di emergenza del sistema elettrico spagnolo che stabilisce i piani di salvaguardia e di ripristino della fornitura di fronte a incidenti critici. Detta le strategie di frammentazione topologica della rete in isole elettriche indipendenti, i percorsi preferenziali di energizzazione e il protocollo di priorità per l'avvio degli impianti di generazione al fine di ripristinare il sistema dopo un calo di tensione parziale o totale.",
  "Procedimiento de Operación 7.4 (P.O. 7.4)": "Procedura Operativa 7.4 (P.O. 7.4)",
  "El P.O. 7.4 es la normativa técnica del sistema eléctrico español que regula el servicio de ajuste de control de tensión en la red de transporte. Define las obligaciones de los generadores para absorber o inyectar potencia reactiva (Q) en función de las consignas enviadas por el Operador del Sistema.": "Il P.O. 7.4 è la normativa tecnica del sistema elettrico spagnolo che regola il servizio di regolazione del controllo di tensione nella rete di trasmissione. Definisce gli obblighi dei generatori di assorbire o iniettare potenza reattiva (Q) in funzione delle istruzioni inviate dall'Operatore di Sistema.",
  "Programa DS3 de EirGrid": "Programma DS3 di EirGrid",
  "El programa Delivering a Secure, Sustainable Electricity System (DS3) es el marco pionero de servicios ancilares de EirGrid (Irlanda), diseñado para operar el sistema insular con penetraciones renovables asíncronas de hasta el 75%.": "Il programma Delivering a Secure, Sustainable Electricity System (DS3) è la cornice pionieristica di servizi ancillari di EirGrid (Irlanda), progettata per operare il sistema insulare con penetrazioni rinnovabili asincrone fino al 75%.",
  "Protecciones de pérdida de sincronismo (OST)": "Protezioni per perdita di sincronismo (OST)",
  "Los relés de pérdida de sincronismo (OST, Out-of-Step Tripping) son esquemas de protección sistémica diseñados para detectar divergencias angulares severas entre áreas interconectadas (deslizamiento de polos). Cuando la diferencia de fase angular excede los límites de estabilidad electromecánica, los relés abren automáticamente las líneas de interconexión para evitar daños estructurales.": "I relè per la perdita di sincronismo (OST, Out-of-Step Tripping) sono schemi di protezione sistemica progettati per rilevare divergenze angolari gravi tra aree interconnesse (scorrimento dei poli). Quando la differenza di fase angolare supera i limiti di stabilità elettromeccanica, i relè aprono automaticamente le linee di interconnessione per evitare danni strutturali.",
  "RCC": "RCC",
  "Regional Coordination Centre.": "Regional Coordination Centre.",
  "REE": "REE",
  "Red Eléctrica de España.": "Rete Elettrica della Spagna.",
  "Régimen de Renovables, Cogeneración y Residuos (RCR)": "Regime delle Rinnovabili, Cogenerazione e Rifiuti (RCR)",
  "El Régimen de Renovables, Cogeneración y Residuos (RCR) es el marco regulatorio del sistema eléctrico español que agrupa a las instalaciones de producción de energía eléctrica a partir de fuentes descarbonizadas.": "Il Regime delle Rinnovabili, Cogenerazione e Rifiuti (RCR) è il quadro normativo del sistema elettrico spagnolo che raggruppa gli impianti di produzione di energia elettrica da fonti decarbonizzate.",
  "Relés de comprobación de sincronismo (Synchro-check)": "Relè di verifica del sincronismo (Synchro-check)",
  "El relé synchro-check (función 25 ANSI) es un dispositivo de protección empleado en las maniobras de acoplamiento de sistemas eléctricos separados (islas). Su función es supervisar continuamente que la tensión, la frecuencia y el ángulo de fase a ambos lados de un interruptor abierto se encuentran dentro de unos márgenes de tolerancia preestablecidos.": "Il relè synchro-check (funzione 25 ANSI) è un dispositivo di protezione impiegato nelle manovre di accoppiamento di sistemi elettrici separati (isole). La sua funzione è quella di monitorare continuamente che la tensione, la frequenza e l'angolo di fase su entrambi i lati di un interruttore aperto rientrino entro margini di tolleranza prestabiliti.",
  "Relés de Deslastre de Carga (UFLS)": "Relè di Distacco del Carico (UFLS)",
  "El Under-Frequency Load Shedding (UFLS, deslastre automático de carga por baja frecuencia) es el mecanismo de último recurso del sistema de defensa: cuando la frecuencia cae por debajo de umbrales predefinidos, los relés de UFLS desconectan cargas de forma automática para restaurar el equilibrio generación-demanda.": "L'Under-Frequency Load Shedding (UFLS, distacco automatico del carico per bassa frequenza) è il meccanismo di ultima istanza del sistema di difesa: quando la frequenza scende al di sotto di soglie predefinite, i relè di UFLS scollegano automaticamente i carichi per ripristinare l'equilibrio generazione-domanda.",
  "Reserva de Restauración de Frecuencia Automática (aFRR)": "Riserva di Ripristino Automatico della Frequenza (aFRR)",
  "La aFRR (automatic Frequency Restoration Reserve), históricamente conocida como regulación secundaria, es un servicio de ajuste del sistema que se activa automáticamente tras una desviación de frecuencia.": "L'aFRR (automatic Frequency Restoration Reserve), storicamente nota come regolazione secondaria, è un servizio di regolazione del sistema che si attiva automaticamente in seguito a una deviazione della frequenza.",
  "RoCoF": "RoCoF",
  "Rate of Change of Frequency (df/dt).": "Tasso di Variazione della Frequenza (df/dt).",
  "SCADA": "SCADA",
  "Supervisory Control and Data Acquisition.": "Controllo di Supervisione e Acquisizione Dati (SCADA).",
  "SCR": "SCR",
  "Short Circuit Ratio.": "Short Circuit Ratio (Rapporto di Cortocircuito).",
  "Servicios Esenciales de Confiabilidad (ERS)": "Servizi Essenziali di Affidabilità (ERS)",
  "Los Servicios Esenciales de Confiabilidad (ERS) agrupan los atributos físicos indispensables para la operación segura de la red, tales como la inercia, la potencia de cortocircuito, la respuesta rápida de frecuencia y el control dinámico de tensión.": "I Servizi Essenziali di Affidabilità (ERS) raggruppano gli attributi fisici indispensabili per l'operazione sicura della rete, come l'inerzia, la potenza di cortocircuito, la risposta rapida in frequenza e il controllo dinamico della tensione.",
  "Sincronismo": "Sincronismo",
  "Condición de operación donde todos los generadores rotan a la misma frecuencia angular. Pérdida de sincronismo = desconexión cascada.": "Condizione operativa in cui tutti i generatori ruotano alla stessa frequenza angolare. Perdita di sincronismo = disconnessione a cascata.",
  "Sistema en por unidad (p.u.)": "Sistema in per unità (p.u.)",
  "El sistema por unidad (p.u.) es una convención de normalización utilizada en ingeniería eléctrica de potencia que expresa las magnitudes del sistema (tensión, corriente, potencia, impedancia) como cocientes adimensionales respecto a valores base de referencia.": "Il sistema in per unità (p.u.) è una convenzione di normalizzazione utilizzata nell'ingegneria elettrica di potenza che esprime le grandezze del sistema (tensione, corrente, potenza, impedenza) come rapporti adimensionali rispetto a valori base di riferimento.",
  "Sistema VOLTAIRE": "Sistema VOLTAIRE",
  "El sistema VOLTAIRE (integrado en el Centro de Control de Energías Renovables, CECRE) es la arquitectura implantada por REE para la regulación dinámica de tensión en el sistema peninsular. Opera en dos capas jerárquicas: la Regulación Terciaria y la Regulación Secundaria.": "Il sistema VOLTAIRE (integrato nel Centro di Controllo delle Energie Rinnovabili, CECRE) è l'architettura implementata da REE per la regolazione dinamica della tensione nel sistema peninsulare. Opera su due livelli gerarchici: la Regolazione Terziaria e la Regolazione Secondaria.",
  "SO GL (System Operation Guidelines)": "SO GL (System Operation Guidelines)",
  "Directrices de Operación del Sistema emitidas por ENTSO-E. Establecen márgenes operacionales mínimos para estabilidad.": "Linee guida per le operazioni di sistema emesse da ENTSO-E. Stabiliscono margini operativi minimi per la stabilità.",
  "SynCon": "SynCon",
  "Synchronous Condenser.": "Synchronous Condenser.",
  "Tasa de Cambio de Frecuencia (RoCoF)": "Tasso di Variazione della Frequenza (RoCoF)",
  "La Rate of Change of Frequency (RoCoF, tasa de cambio de frecuencia) cuantifica la velocidad de variación de la frecuencia del sistema ante una perturbación, expresada típicamente en Hz/s. Es el parámetro dinámico más crítico para la estabilidad transitoria: un RoCoF elevado reduce el tiempo disponible para que los sistemas de regulación actúen, acelerando la cascada de desconexiones de protecciones.": "Il Rate of Change of Frequency (RoCoF, tasso di variazione della frequenza) quantifica la velocità di variazione della frequenza del sistema di fronte a una perturbazione, espressa tipicamente in Hz/s. È il parametro dinamico più critico per la stabilità transitoria: un RoCoF elevato riduce il tempo a disposizione affinché i sistemi di regolazione intervengano, accelerando la cascata di disconnessioni delle protezioni.",
  "TSO": "TSO",
  "Transmission System Operator.": "Transmission System Operator.",
  "UFLS": "UFLS",
  "Under-Frequency Load Shedding.": "Under-Frequency Load Shedding.",
  "V2G": "V2G",
  "Vehicle-to-Grid.": "Vehicle-to-Grid.",
  "Vacuum filling (Relleno del vacío informativo)": "Vacuum filling (Riempimento del vuoto informativo)",
  "El vacuum filling es el proceso estructural e inevitable mediante el cual la incertidumbre colectiva ante un desastre genera una demanda de respuestas que, si no es satisfecha por las instituciones oficiales, es cubierta espontáneamente por fuentes no autorizadas.": "Il vacuum filling è il processo strutturale e inevitabile attraverso il quale l'incertezza collettiva di fronte a un disastro genera una domanda di risposte che, se non soddisfatta dalle istituzioni ufficiali, viene coperta spontaneamente da fonti non autorizzate.",
  "Vehicle-to-Grid (V2G)": "Vehicle-to-Grid (V2G)",
  "La tecnología Vehicle-to-Grid (V2G) habilita la bidireccionalidad de las baterías de los vehículos eléctricos, permitiéndoles inyectar potencia activa y reactiva hacia la red.": "La tecnologia Vehicle-to-Grid (V2G) abilita la bidirezionalità delle batterie dei veicoli elettrici, consentendo loro di iniettare potenza attiva e reattiva verso la rete.",
  "WAMS": "WAMS",
  "Wide Area Monitoring System.": "Wide Area Monitoring System.",
  "Inercia (H)": "Inerzia (H)",
  "La constante de inercia H es un parámetro adimensional que cuantifica la energía cinética almacenada en las masas rotatorias de un generador síncrono respecto a su potencia nominal. Cuanto mayor es H, más lento es el cambio de frecuencia ante perturbaciones (mayor RoCoF tolerable). El 28A el sistema operaba con H ≈ 2,3 s a nivel peninsular, pero con valores zonales de 1,3–1,8 s en el sur.": "La costante d'inerzia H è un parametro adimensionale che quantifica l'energia cinetica immagazzinata nelle masse rotanti di un generatore sincrono rispetto alla sua potenza nominale. Quanto maggiore è H, tanto più lento è il cambiamento di frequenza in seguito a perturbazioni (maggiore tollerabilità del RoCoF). Nel 28A il sistema operava con H ≈ 2,3 s a livello peninsulare, ma con valori di zona di 1,3-1,8 s nel sud.",
  "Potencia reactiva": "Potenza reattiva",
  "Componente de la potencia eléctrica asociada al almacenamiento y liberación de energía en campos eléctricos y magnéticos (no disipada como calor). Se mide en VAr. El balance de potencia reactiva determina el perfil de tensión en la red: un exceso de reactiva capacitiva eleva la tensión (sobretensión); un déficit la deprime. El 28A el colapso se debió fundamentalmente a un exceso de reactiva capacitiva inyectada por las líneas en vacío tras el mallado.": "Componente della potenza elettrica associata all'immagazzinamento e al rilascio di energia in campi elettrici e magnetici (non dissipata sotto forma di calore). Si misura in VAr. Il bilancio della potenza reattiva determina il profilo di tensione nella rete: un eccesso di reattiva capacitiva aumenta la tensione (sovratensione); un deficit la riduce. Nel 28A il collasso è stato dovuto principalmente a un eccesso di reattiva capacitiva iniettata dalle linee a vuoto in seguito alla magliatura.",
  "Potencia activa": "Potenza attiva",
  "Componente de la potencia eléctrica que realiza trabajo útil. Se mide en vatios (W). Es la potencia que efectivamente consume la carga. Se controla mediante el despacho de generación y determina el equilibrio de frecuencia del sistema.": "Componente della potenza elettrica che svolge un lavoro utile. Si misura in watt (W). È la potenza che il carico consuma effettivamente. Viene controllata attraverso il dispacciamento della generazione e determina l'equilibrio della frequenza del sistema.",
  "Black Start": "Black Start",
  "Véase \"Arranque autónomo (Black Start)\". Capacidad de ciertas instalaciones de generación de arrancar sin tensión externa de red para liderar la reposición del suministro tras un colapso total.": "Vedere \"Avvio autonomo (Black Start)\". Capacità di alcune strutture di generazione di avviarsi senza tensione esterna di rete per guidare il ripristino dell'alimentazione dopo un collasso totale.",
  "Tap-Lag": "Tap-Lag",
  "Fenómeno por el cual la inercia mecánica de los Cambiadores de Tomas en Carga (OLTC) introduce un retardo de decenas de segundos en el ajuste de la relación de transformación. Durante el 28A, los OLTCs habían subido tomas para compensar caídas de tensión previas; cuando llegó la sobretensión, no pudieron bajarlas a tiempo, amplificando la tensión hacia las redes colectoras de 220 kV y generando un \"punto ciego\" de observabilidad en el SCADA de REE.": "Fenomeno in cui l'inerzia meccanica dei Commutatori di Prese Sotto Carico (OLTC) introduce un ritardo di decine di secondi nella regolazione del rapporto di trasformazione. Durante il 28A, gli OLTC avevano aumentato le prese per compensare le precedenti cadute di tensione; quando è arrivata la sovratensione, non sono riusciti ad abbassarle in tempo, amplificando la tensione verso le reti collettrici a 220 kV e generando un \"punto cieco\" di osservabilità nello SCADA di REE.",
  "NC RfG": "NC RfG",
  "Network Code on Requirements for Generators. Véase \"Network Code on Requirements for Generators (NC RfG)\".": "Network Code on Requirements for Generators. Vedere \"Network Code on Requirements for Generators (NC RfG)\".",
  "GFL (Grid-Following)": "GFL (Grid-Following)",
  "Modo de operación de inversores en el que el equipo se sincroniza pasivamente con la tensión y frecuencia de la red mediante un algoritmo PLL (Phase-Locked Loop). Requiere una red externa estable y no puede operar de forma autónoma. El 78% del parque IBR del 28A operaba en modo grid-following.": "Modalità di funzionamento degli inverter in cui l'apparecchiatura si sincronizza passivamente con la tensione e la frequenza di rete mediante un algoritmo PLL (Phase-Locked Loop). Richiede una rete esterna stabile e non può funzionare in modo autonomo. Il 78% del parco IBR del 28A operava in modalità grid-following.",
  "GFM (Grid-Forming)": "GFM (Grid-Forming)",
  "Modo de operación de inversores en el que el equipo actúa como una fuente de tensión ideal, estableciendo activamente su propia onda de tensión y frecuencia. Puede sostener la red de forma autónoma y responder a perturbaciones sin necesidad de una referencia externa. Es la tecnología clave propuesta por ENTSO-E en el NC RfG 2.0 para sistemas con alta penetración renovable.": "Modalità di funzionamento degli inverter in cui l'apparecchiatura agisce come una fonte di tensione ideale, stabilendo attivamente la propria forma d'onda di tensione e di frequenza. Può sostenere autonomamente la rete e rispondere alle perturbazioni senza bisogno di un riferimento esterno. È la tecnologia chiave proposta da ENTSO-E nella NC RfG 2.0 per i sistemi ad alta penetrazione di fonti rinnovabili.",
  "Phase-Locked Loop (PLL)": "Phase-Locked Loop (PLL)",
  "Véase \"PLL\". Algoritmo de control electrónico que sincroniza la salida de un inversor con la tensión y frecuencia de la red. Su dependencia de una red estable es la limitación estructural de los inversores grid-following.": "Vedere \"PLL\". Algoritmo di controllo elettronico che sincronizza l'uscita di un inverter con la tensione e la frequenza di rete. La sua dipendenza da una rete stabile è il limite strutturale degli inverter grid-following.",
  "SCADA (Supervisory Control and Data Acquisition)": "SCADA (Supervisory Control and Data Acquisition)",
  "Véase \"SCADA\". Sistema de supervisión y control en tiempo real de la red eléctrica. Durante el 28A, el SCADA de REE mostraba tensiones en la red de 400 kV dentro de límites normativos (418 kV en Granada) mientras el fenómeno Tap-Lag generaba sobretensiones reales de 244 kV en el secundario de 220 kV, invisible al operador.": "Vedere \"SCADA\". Sistema di supervisione e controllo in tempo reale della rete elettrica. Durante il 28A, lo SCADA di REE mostrava tensioni di rete a 400 kV entro i limiti normativi (418 kV a Granada) mentre il fenomeno del Tap-Lag generava sovratensioni reali di 244 kV al secondario a 220 kV, invisibili all'operatore.",
  "WAMS (Wide Area Monitoring Systems)": "WAMS (Wide Area Monitoring Systems)",
  "Véase \"WAMS\". Sistema de monitorización de área extensa basado en PMUs sincronizadas por GPS. Permite observar la dinámica de la red en escalas geográficas continentales con resolución de milisegundos.": "Vedere \"WAMS\". Sistema di monitoraggio di area vasta basato su PMU sincronizzate via GPS. Consente di osservare le dinamiche di rete su scale geografiche continentali con una risoluzione al millisecondo.",
  "PMU (Phasor Measurement Unit)": "PMU (Phasor Measurement Unit)",
  "Véase \"PMU\". Unidad de Medición Fasorial. Dispositivo que mide sincronizadamente tensión y corriente en múltiples puntos de la red con resolución temporal de milisegundos, esencial para el análisis de oscilaciones inter-área.": "Vedere \"PMU\". Phasor Measurement Unit. Dispositivo che misura la tensione e la corrente in modo sincrono in più punti della rete con una risoluzione temporale al millisecondo, essenziale per l'analisi delle oscillazioni inter-area.",
  "RoCoF (Rate of Change of Frequency)": "RoCoF (Rate of Change of Frequency)",
  "Véase \"Tasa de Cambio de Frecuencia (RoCoF)\" y \"RoCoF\". Parámetro dinámico crítico que cuantifica la velocidad de variación de la frecuencia (Hz/s) ante perturbaciones.": "Vedere \"Tasso di Variazione della Frequenza (RoCoF)\" e \"RoCoF\". Parametro dinamico critico che quantifica la velocità di variazione della frequenza (Hz/s) di fronte alle perturbazioni.",
  "UFLS (Underfrequency Load Shedding)": "UFLS (Underfrequency Load Shedding)",
  "Véase \"Relés de Deslastre de Carga (UFLS)\". Mecanismo automático de desconexión de cargas cuando la frecuencia cae por debajo de umbrales predefinidos, para restaurar el equilibrio generación-demanda.": "Vedere \"Relè di Distacco del Carico (UFLS)\". Meccanismo automatico per scollegare i carichi quando la frequenza scende al di sotto di soglie predefinite, al fine di ripristinare l'equilibrio generazione-domanda.",
  "EAS (ENTSO-E Awareness System)": "EAS (ENTSO-E Awareness System)",
  "Véase \"EAS (ENTSO-E Awareness System)\". Sistema de Conciencia Situacional de ENTSO-E para monitorización en tiempo real del sistema eléctrico europeo.": "Vedere \"EAS (ENTSO-E Awareness System)\". Sistema di consapevolezza situazionale ENTSO-E per il monitoraggio in tempo reale del sistema elettrico europeo.",
  "OLTC (On-Load Tap Changer)": "OLTC (On-Load Tap Changer)",
  "Véase \"Cambiadores de Tomas en Carga (OLTC)\". Mecanismo electromecánico en transformadores de potencia que ajusta la relación de transformación sin interrumpir el servicio, con un retardo mecánico de varios segundos por escalón.": "Vedere \"Commutatori di Prese Sotto Carico (OLTC)\". Meccanismo elettromeccanico nei trasformatori di potenza che regola il rapporto di trasformazione senza interrompere il servizio, con un ritardo meccanico di diversi secondi per gradino.",
  "SO GL (System Operation Guidelines)": "SO GL (System Operation Guidelines)",
  "Véase \"SO GL (System Operation Guidelines)\". Directrices de Operación del Sistema de ENTSO-E que definen cinco niveles de severidad operativa (Normal, Alerta, Emergencia, Blackout, Restauración).": "Vedere \"SO GL (System Operation Guidelines)\". Linee guida di ENTSO-E per il funzionamento del sistema che definiscono cinque livelli di gravità operativa (Normale, Allerta, Emergenza, Blackout, Ripristino).",
  "Capacidad Neta de Transferencia (NTC)": "Capacità Netta di Trasferimento (NTC)",
  "Net Transfer Capacity (NTC). Capacidad máxima de intercambio de energía entre dos zonas de control pactada ex ante entre operadores de sistema vecinos (REE y RTE en el caso ibérico). El 28A, el NTC de la interconexión España-Francia estaba en torno al 3% de la demanda peninsular, muy por debajo del objetivo europeo del 15%.": "Net Transfer Capacity (NTC). Capacità massima di scambio di energia tra due aree di controllo concordata ex ante tra i gestori di sistema vicini (REE e RTE nel caso iberico). Il 28A, la NTC dell'interconnessione Spagna-Francia era circa il 3% della domanda peninsulare, ben al di sotto dell'obiettivo europeo del 15%.",
  "Ratio de amortiguamiento": "Rapporto di smorzamento",
  "El ratio de amortiguamiento (o amortiguamiento relativo) es un indicador adimensional que cuantifica la rapidez con la que una oscilación se atenúa tras una perturbación. Valores próximos al 5 \\% se consideran un margen de seguridad operativo razonable en el sistema síncrono europeo; valores cercanos al 0 \\% indican oscilaciones sostenidas, y valores negativos implican un crecimiento de la amplitud y, por tanto, un riesgo de inestabilidad.": "Il rapporto di smorzamento (o smorzamento relativo) è un indicatore adimensionale che quantifica la rapidità con cui un'oscillazione si attenua dopo una perturbazione. Valori prossimi al 5 \\% sono considerati un margine di sicurezza operativo ragionevole nel sistema sincrono europeo; valori vicini allo 0 \\% indicano oscillazioni sostenute, e valori negativi implicano una crescita dell'ampiezza e, quindi, un rischio di instabilità.",
  "Potencia de cortocircuito": "Potenza di cortocircuito",
  "La potencia de cortocircuito ($S_{sc}$) en un nudo de la red es una medida de su \"fortaleza\" electromagnética. Representa la cantidad de corriente aparente que fluiría hacia ese nudo en caso de producirse un cortocircuito franco trifásico. Una elevada potencia de cortocircuito, típicamente aportada por los grandes generadores síncronos, implica que la tensión en ese nudo es muy robusta y resiliente, sufriendo variaciones mínimas ante perturbaciones, conexiones de cargas bruscas o maniobras en la red.": "La potenza di cortocircuito ($S_{sc}$) in un nodo di rete è una misura della sua \"forza\" elettromagnetica. Rappresenta la quantità di corrente apparente che fluirebbe verso quel nodo nel caso di un cortocircuito franco trifase. Un'elevata potenza di cortocircuito, tipicamente fornita da grandi generatori sincroni, implica che la tensione in quel nodo è molto robusta e resiliente e subisce variazioni minime a fronte di perturbazioni, collegamenti improvvisi di carichi o manovre di rete.",
  "Estrategia Brownfield": "Strategia Brownfield",
  "En ingeniería de infraestructuras energéticas, la estrategia Brownfield consiste en la reconversión de instalaciones industriales existentes —como las centrales térmicas o nucleares clausuradas— para dotarlas de nuevas funciones sistémicas. En este contexto, implica conservar los grandes alternadores originales operando en vacío como compensadores síncronos, aportando inercia natural y potencia de cortocircuito, y aprovechando las subestaciones y líneas de evacuación ya construidas para reducir drásticamente costes y tiempos de implementación.": "Nell'ingegneria delle infrastrutture energetiche, la strategia Brownfield consiste nella riconversione di impianti industriali esistenti —come centrali termiche o nucleari chiuse— per dotarli di nuove funzioni sistemiche. In questo contesto, implica mantenere i grandi alternatori originali funzionanti a vuoto come compensatori sincroni, fornendo inerzia naturale e potenza di cortocircuito, e sfruttando le sottostazioni e le linee di evacuazione già costruite per ridurre drasticamente i costi e i tempi di implementazione.",
  "Sistema por Unidad (p.u.)": "Sistema per Unità (p.u.)",
  "El sistema por unidad (p.u.) es una convención de normalización utilizada en ingeniería eléctrica de potencia que expresa las magnitudes del sistema (tensión, corriente, potencia, impedancia) como cocientes adimensionales respecto a valores base de referencia. La base de tensión suele tomarse como el valor nominal de la red en el nudo de análisis, y la base de potencia como la potencia aparente nominal del equipo o del sistema. La ventaja principal es la eliminación de las transformaciones de escala al analizar redes con múltiples niveles de tensión interconectados mediante transformadores. En el contexto del análisis de inversores, la expresión de las corrientes de falta en p.u. permite comparar directamente la capacidad de inyección de los inversores (1{,}1–1{,}2 p.u.) con la de los generadores síncronos (5–7 p.u.) con independencia de la potencia nominal de cada tecnología.": "Il sistema per unità (p.u.) è una convenzione di normalizzazione utilizzata nell'ingegneria elettrica di potenza che esprime le grandezze del sistema (tensione, corrente, potenza, impedenza) come rapporti adimensionali rispetto a valori di base di riferimento. La base di tensione viene solitamente considerata come il valore nominale della rete nel nodo in analisi e la base di potenza come la potenza apparente nominale dell'apparecchiatura o del sistema. Il vantaggio principale è l'eliminazione delle trasformazioni di scala nell'analisi di reti con più livelli di tensione interconnessi mediante trasformatori. Nel contesto dell'analisi degli inverter, l'espressione delle correnti di guasto in p.u. consente di confrontare direttamente la capacità di iniezione degli inverter (1{,}1–1{,}2 p.u.) con quella dei generatori sincroni (5–7 p.u.) indipendentemente dalla potenza nominale di ciascuna tecnologia.",
  "GFL vs GFM (Grid-Following vs Grid-Forming)": "GFL vs GFM (Grid-Following vs Grid-Forming)",
  "La topología Grid-Following (GFL) modela al inversor como una fuente de corriente controlada que depende de una medición externa de la tensión de red (a través del lazo de seguimiento de fase, PLL). Su ventaja es la simplicidad y el bajo coste; su limitación crítica es que no puede operar de forma autónoma ni establecer tensión en redes débiles. La topología Grid-Forming (GFM) modela el inversor como una fuente de tensión ideal detrás de una reactancia virtual, permitiendo operación autónoma, inyección de corrientes de falta robustas e inercia sintética. El NC RfG 2.0 establece la transición hacia GFM como obligatoria para nuevas instalaciones significativas.": "La topologia Grid-Following (GFL) modella l'inverter come una sorgente di corrente controllata che dipende da una misurazione esterna della tensione di rete (attraverso l'anello ad aggancio di fase, PLL). Il suo vantaggio è la semplicità e il basso costo; il suo limite critico è che non può operare in modo autonomo o stabilire la tensione in reti deboli. La topologia Grid-Forming (GFM) modella l'inverter come una fonte di tensione ideale dietro una reattanza virtuale, consentendo il funzionamento autonomo, l'iniezione di robuste correnti di guasto e l'inerzia sintetica. L'NC RfG 2.0 stabilisce la transizione a GFM come obbligatoria per le nuove installazioni significative.",
  "Curva de Pato (Duck Curve)": "Curva ad Anatra (Duck Curve)",
  "La curva de pato describe el perfil diario de demanda neta de regulación en sistemas con alta penetración solar: una depresión profunda durante las horas centrales del día (cuando el consumo base es bajo pero la generación solar es máxima) seguida de una rampa vespertina pronunciada. La primavera es el período de máxima profundidad y vulnerabilidad. En el caso del 28A, la profundidad del valle coincidió con una rampa de inyección solar extraordinariamente aguda, dejando al sistema con mínima capacidad de absorción de reactiva en el instante crítico.": "La curva ad anatra descrive il profilo giornaliero della domanda netta di regolazione nei sistemi ad alta penetrazione solare: una profonda depressione durante le ore centrali della giornata (quando il consumo di base è basso ma la generazione solare è massima) seguita da una ripida rampa serale. La primavera è il periodo di massima profondità e vulnerabilità. Nel caso del 28A, la profondità della valle coincise con una rampa di iniezione solare straordinariamente ripida, lasciando al sistema una capacità minima di assorbimento della reattiva nell'istante critico.",
  "Headroom": "Headroom",
  "El headroom es la fracción de la capacidad aparente máxima ($S_{}$) que un inversor GFM debe mantener reservada sin utilizarla para la inyección de potencia activa en estado estacionario. Esta reserva es necesaria para garantizar que el inversor dispone de margen suficiente para actuar ante perturbaciones rápidas de tensión o frecuencia. Exigir headroom reduce los ingresos del mercado de energía, lo que constituye la fricción económica estructural que justifica la creación de mercados de Servicios Esenciales de Confiabilidad (ERS) para remunerar explícitamente esta capacidad de respuesta.": "L'headroom è la frazione della capacità apparente massima ($S_{}$) che un inverter GFM deve tenere in riserva senza utilizzarla per l'iniezione di potenza attiva allo stato stazionario. Questa riserva è necessaria per garantire che l'inverter abbia un margine sufficiente per reagire a rapidi disturbi di tensione o di frequenza. La richiesta di headroom riduce i ricavi dal mercato dell'energia, costituendo l'attrito economico strutturale che giustifica la creazione di mercati per i Servizi Essenziali di Affidabilità (ERS) per remunerare esplicitamente questa capacità di risposta.",
  "LVRT (Low Voltage Ride Through)": "LVRT (Low Voltage Ride Through)",
  "El Low Voltage Ride Through (LVRT) es la capacidad de un inversor para mantener la inyección de energía durante un hueco de tensión en lugar de desconectarse por protección. Los requisitos del LVRT en España están regulados por el P.O. 12.3 e incluyen el parámetro dinámico $k$ (factor de proporcionalidad de corriente reactiva respecto a la profundidad del hueco). El apagón del 28A evidenció que en redes con $SCR < 2$, la inyección masiva de reactiva según los perfiles tradicionales de LVRT puede amplificar la inestabilidad en lugar de contenerla, requiriendo revisión de la coordinación entre el control LVRT y la debilidad de red.": "Il Low Voltage Ride Through (LVRT) è la capacità di un inverter di mantenere l'iniezione di potenza durante un buco di tensione invece di disconnettersi per protezione. I requisiti per l'LVRT in Spagna sono regolati dalla P.O. 12.3 e includono il parametro dinamico $k$ (fattore di proporzionalità della corrente reattiva rispetto alla profondità del buco). Il blackout del 28A ha evidenziato che in reti con $SCR < 2$, la massiccia iniezione di reattiva secondo i profili LVRT tradizionali può amplificare l'instabilità anziché contenerla, richiedendo una revisione del coordinamento tra controllo LVRT e debolezza della rete."
};

let fileContent = fs.readFileSync('src/data/glossary.js', 'utf8');

const termRegex = /term:\s*'([^']+)'/g;
let termMatch;
const termMatches = [];
while ((termMatch = termRegex.exec(fileContent)) !== null) {
  termMatches.push({ full: termMatch[0], text: termMatch[1] });
}

for (let item of termMatches) {
  if (translations[item.text]) {
    const safeTranslation = translations[item.text].replace(/'/g, "\\'");
    fileContent = fileContent.replace(item.full, `term: '${safeTranslation}'`);
  }
}

const defRegex = /definition:\s*'([^']+)'/g;
let defMatch;
const defMatches = [];
while ((defMatch = defRegex.exec(fileContent)) !== null) {
  defMatches.push({ full: defMatch[0], text: defMatch[1] });
}

for (let item of defMatches) {
  if (translations[item.text]) {
    const safeTranslation = translations[item.text].replace(/'/g, "\\'");
    fileContent = fileContent.replace(item.full, `definition: '${safeTranslation}'`);
  }
}

fs.writeFileSync('src/data/glossary_it.js', fileContent);
console.log('Saved src/data/glossary_it.js using internal translations!');
